<?php $title='Thư viện tính năng Admin'; ?>
<div class="page-head"><div><span class="eyebrow">PLATFORM ADMIN</span><h1>Thư viện tính năng</h1><p>Admin quản lý các tính năng mà các dự án có thể sử dụng. Chủ dự án chỉ được thêm tính năng có sẵn từ thư viện này.</p></div></div>
<section class="panel"><div class="panel-head"><div><h2>Thêm tính năng dùng chung</h2><p>Tính năng mới sẽ xuất hiện trong thư viện để chủ dự án chọn dùng.</p></div></div><form method="post" action="<?= e(url('admin/features/create')) ?>" class="form-grid"><?= csrf_field() ?><label>Feature key<input name="key" required pattern="[a-z][a-z0-9_]{1,119}" placeholder="new_checkout"></label><label>Tên hiển thị<input name="name" required maxlength="160"></label><label class="wide">Mô tả<input name="description" maxlength="500"></label><button class="button primary" type="submit">Thêm vào thư viện</button></form></section>
<section class="panel"><div class="panel-head"><div><h2>Các tính năng có sẵn</h2><p><?= count(array_filter($features, function ($feature) { return (int)$feature['is_active'] === 1; })) ?> đang hoạt động</p></div></div><?php if(!$features): ?><p class="empty">Thư viện chưa có tính năng.</p><?php else: ?><?php foreach($features as $feature): ?><div class="group-row"><div><strong><?= e($feature['name']) ?></strong><small><code><?= e($feature['key']) ?></code> · <?= e($feature['description']) ?></small></div><span class="pill <?= $feature['is_active']?'green':'gray' ?>"><?= $feature['is_active']?'ĐANG CUNG CẤP':'ĐÃ NGỪNG' ?></span><?php if($feature['is_active']): ?><form method="post" action="<?= e(url('admin/features/deactivate')) ?>" onsubmit="return confirm('Ngừng cung cấp tính năng này cho tất cả dự án?')"><?= csrf_field() ?><input type="hidden" name="feature_id" value="<?= (int)$feature['id'] ?>"><button class="button danger small" type="submit">Ngừng cung cấp</button></form><?php endif; ?></div><?php endforeach; ?><?php endif; ?></section>
